sources = [
    {"id": "s1", "text": "Remote work increased average reported productivity by 13 percent in one 2021 study."},
    {"id": "s2", "text": "A separate 2022 survey found remote work decreased team collaboration scores by 8 percent."},
]

def decompose_question(question):
    # breaks the broad question into independently answerable sub-questions
    return ["effect of remote work on productivity", "effect of remote work on collaboration"]

def retrieve_for_subquestion(subquestion, sources):
    return [s for s in sources if any(w in s["text"].lower() for w in subquestion.lower().split())]

def synthesize(subquestions, sources):
    # each claim carries its own source citation
    synthesis = []
    for sq in subquestions:
        matches = retrieve_for_subquestion(sq, sources)
        for m in matches:
            synthesis.append(f"{m['text']} [source: {m['id']}]")
    return synthesis

question = "What is the overall effect of remote work?"
subquestions = decompose_question(question)
result = synthesize(subquestions, sources)

print("Research synthesis:")
for claim in result:
    print(f"  {claim}")
